import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { fileURLToPath } from 'node:url';
import { setTimeout as delay } from 'node:timers/promises';
import { openClockProbe, compareClocks } from './zhiliao-a2-clock-probe-20260912.mjs';

const repo = 'D:/ClaudeProjects/ai_acknowladge';
const sourcePath = fileURLToPath(import.meta.url);
const sha = bytes => crypto.createHash('sha256').update(bytes).digest('hex');
const input = 'docs/验收证据/story-2-2-clock-diagnostics-2026-09-12T04-59-16-594Z.json';
const diagnosis = JSON.parse(fs.readFileSync(path.join(repo, input), 'utf8'));
const channelInput = 'docs/验收证据/story-2-2-root-channel-audit-2026-09-12T09-33-17-334Z.json';
const channel = JSON.parse(fs.readFileSync(path.join(repo, channelInput), 'utf8'));
if (channel.status !== 'passed' || sha(diagnosis.python_probe) !== diagnosis.python_probe_sha256) throw new Error('只读前提未通过');
const source = fs.readFileSync(sourcePath, 'utf8');
const probeModule = fs.readFileSync(new URL('./zhiliao-a2-clock-probe-20260912.mjs', import.meta.url), 'utf8');
const report = {
  story: '2.2', recorded_at: new Date().toISOString(), status: 'failed',
  scope: '重启后正常环境的两段 20 秒只读对照；不暂停进程、不写时钟参数、不启动代理。',
  channel_input: channelInput, channel_input_sha256: sha(fs.readFileSync(path.join(repo, channelInput))),
  boot_id: channel.identity.boot_id, source_file: path.basename(sourcePath), source_sha256: sha(source), maintenance_source: source,
  clock_probe_module: probeModule, clock_probe_module_sha256: sha(probeModule),
  python_probe: diagnosis.python_probe, python_probe_sha256: diagnosis.python_probe_sha256,
  maximum_relative_error: 0.01, interval_ms: 20000, samples: [], intervals: [], signals_sent: [], clock_writes: [],
};
const evidencePath = path.join(repo, 'docs/验收证据/story-2-2-normal-clock-' + report.recorded_at.replace(/[:.]/g, '-') + '.json');
if (fs.existsSync(evidencePath)) throw new Error('证据已存在');
let probe;
try {
  probe = openClockProbe(diagnosis.python_probe, repo);
  await probe.sample();
  let before = await probe.endpoint();
  console.log(JSON.stringify({stage: 'normal_clock_started', at: new Date().toISOString(), tick: before.guest.timex.tick_us}));
  for (let index = 0; index < 2; index++) {
    await delay(20000);
    const after = await probe.endpoint();
    const interval = compareClocks(before, after);
    report.intervals.push(interval);
    console.log(JSON.stringify({stage: 'normal_clock_interval', index: index + 1, ...interval, tick: after.guest.timex.tick_us}));
    before = after;
  }
  report.status = report.intervals.every(value => value.passed) ? 'passed' : 'failed';
} catch (error) { report.error = error.message; }
finally {
  if (probe) { report.probe_exit = await probe.close(); report.samples = probe.samples; }
  report.finished_at = new Date().toISOString();
  fs.writeFileSync(evidencePath, JSON.stringify(report, null, 2) + '\n', {flag: 'wx'});
  console.log(JSON.stringify({stage: 'finished', status: report.status, evidence: path.relative(repo, evidencePath).replaceAll('\\', '/')}));
}
process.exitCode = report.status === 'passed' ? 0 : 1;

