import { spawn } from 'node:child_process';
import { createInterface } from 'node:readline';
import { setTimeout as delay } from 'node:timers/promises';

export function compareClocks(before, after) {
  const lower = after.host_before_ms - before.host_after_ms;
  const upper = after.host_after_ms - before.host_before_ms;
  if (!(lower > 0 && upper >= lower)) throw new Error('宿主机采样区间无效');
  const clocks = {};
  for (const name of ['monotonic_ns', 'raw_ns']) {
    const guestMs = Number(BigInt(after.guest[name]) - BigInt(before.guest[name])) / 1e6;
    const errorLower = guestMs / upper - 1;
    const errorUpper = guestMs / lower - 1;
    clocks[name] = {guest_ms: guestMs, relative_error_lower: errorLower, relative_error_upper: errorUpper,
      passed: errorLower >= -0.01 && errorUpper <= 0.01};
  }
  return {before_id: before.guest.id, after_id: after.guest.id, host_lower_ms: lower, host_upper_ms: upper,
    clocks, passed: Object.values(clocks).every(value => value.passed)};
}

export function openClockProbe(source, cwd) {
  const child = spawn('wsl.exe', ['-d', 'Ubuntu-24.04', '-u', 'root', '--', 'python3', '-u', '-c', source], {
    cwd, windowsHide: true, stdio: ['pipe', 'pipe', 'pipe'],
  });
  const pending = new Map();
  const samples = [];
  let failure, sequence = 0, expectedClose = false;
  const stderr = [];
  const fail = error => {
    if (!expectedClose) failure ??= error;
    for (const item of pending.values()) { clearTimeout(item.timer); item.reject(error); }
    pending.clear();
  };
  child.on('error', fail);
  child.stdin.on('error', fail);
  child.stderr.on('data', data => { if (stderr.reduce((total, value) => total + value.length, 0) < 8192) stderr.push(data); });
  const closed = new Promise(resolve => child.on('close', (code, signal) => { fail(new Error('只读探针结束')); resolve({code, signal}); }));
  const lines = createInterface({input: child.stdout, crlfDelay: Infinity});
  lines.on('line', line => {
    const hostAfter = performance.now();
    try {
      const guest = JSON.parse(line);
      const item = pending.get(guest.id);
      if (!item) return;
      if (guest.timex.modes_input !== 0 || guest.timex.result < 0) throw new Error('只读 adjtimex 结果异常');
      pending.delete(guest.id);
      clearTimeout(item.timer);
      const sample = {host_before_ms: item.before, host_after_ms: hostAfter, round_trip_ms: hostAfter - item.before, guest};
      samples.push(sample);
      item.resolve(sample);
    } catch (error) { fail(error); }
  });
  async function sample() {
    if (failure) throw failure;
    const id = 'a2-' + (++sequence);
    return new Promise((resolve, reject) => {
      const timer = setTimeout(() => { pending.delete(id); reject(new Error('只读探针 5 秒未响应')); }, 5000);
      pending.set(id, {resolve, reject, timer, before: performance.now()});
      child.stdin.write(id + '\n');
    });
  }
  async function endpoint() {
    const group = [];
    for (let i = 0; i < 3; i++) { group.push(await sample()); if (i < 2) await delay(10); }
    return group.sort((a, b) => a.round_trip_ms - b.round_trip_ms)[0];
  }
  async function close() {
    expectedClose = true;
    child.stdin.end();
    const timer = setTimeout(() => child.kill(), 3000);
    const result = await closed;
    clearTimeout(timer);
    lines.close();
    return {...result, windows_pid: child.pid, stderr_base64: Buffer.concat(stderr).toString('base64')};
  }
  return {sample, endpoint, close, samples};
}
